  new file mode 100644
  index 0000000..c593d08
  --- /dev/null
  +++ b/web/src/keating/model-capabilities.ts
  @@ -0,0 +1,38 @@
  +import type { Api, Model } from "@earendil-works/pi-ai/compat";
  +
  +export const LONG_CONTEXT_THRESHOLD = 100_000;
  +export const LARGE_OUTPUT_THRESHOLD = 16_000;
  +
  +export const CHAT_CAPABILITY_FILTERS = [
  +	{ value: "all", label: "All chat models" },
  +	{ value: "thinking", label: "Thinking" },
  +	{ value: "vision", label: "Vision" },
  +	{ value: "long-context", label: "Long context" },
  +	{ value: "large-output", label: "Large output" },
  +] as const;
  +
  +export type ChatCapabilityFilter = (typeof CHAT_CAPABILITY_FILTERS)[number]["value"];
  +
  +export function modelHasCapability(model: Model<Api>, capability: ChatCapabilityFilter): boolean {
  +	switch (capability) {
  +		case "thinking":
  +			return model.reasoning === true;
  +		case "vision":
  +			return model.input.includes("image");
  +		case "long-context":
  +			return model.contextWindow >= LONG_CONTEXT_THRESHOLD;
  +		case "large-output":
  +			return model.maxTokens >= LARGE_OUTPUT_THRESHOLD;
  +		default:
  +			return true;
  +	}
  +}
  +
  +export function modelCapabilityBadges(model: Model<Api>): string[] {
  +	return [
  +		model.input.includes("image") ? "Vision" : "",
  +		model.reasoning ? "Thinking" : "",
  +		model.contextWindow >= LONG_CONTEXT_THRESHOLD ? "Long context" : "",
  +		model.maxTokens >= LARGE_OUTPUT_THRESHOLD ? "Large output" : "",
  +	].filter(Boolean);
  +}

  diff --git a/web/src/test/model-capabilities.test.ts b/web/src/test/model-capabilities.test.ts
  new file mode 100644
  index 0000000..6f0b847
  --- /dev/null
  +++ b/web/src/test/model-capabilities.test.ts
  @@ -0,0 +1,54 @@
  +import { describe, expect, test } from "bun:test";
  +import type { Api, Model } from "@earendil-works/pi-ai/compat";
  +import {
  +	modelCapabilityBadges,
  +	modelHasCapability,
  +} from "../keating/model-capabilities";
  +
  +function model(overrides: Partial<Model<Api>> = {}): Model<Api> {
  +	return {
  +		id: "test-model",
  +		name: "Test model",
  +		api: "openai-completions" as Api,
  +		provider: "test",
  +		baseUrl: "https://example.test/v1",
  +		reasoning: false,
  +		input: ["text"],
  +		cost: { input: 1, output: 1, cacheRead: 0, cacheWrite: 0 },
  +		contextWindow: 32_000,
  +		maxTokens: 4_096,
  +		...overrides,
  +	};
  +}
  +
  +describe("model capability filters", () => {
  +	test("uses declared model metadata for each filter", () => {
  +		const capable = model({
  +			reasoning: true,
  +			input: ["text", "image"],
  +			contextWindow: 128_000,
  +			maxTokens: 16_000,
  +		});
  +
  +		expect(modelHasCapability(capable, "thinking")).toBe(true);
  +		expect(modelHasCapability(capable, "vision")).toBe(true);
  +		expect(modelHasCapability(capable, "long-context")).toBe(true);
  +		expect(modelHasCapability(capable, "large-output")).toBe(true);
  +	});
  +
  +	test("does not infer unsupported capabilities from a model name", () => {
  +		const plain = model({ id: "vision-thinking-1m", name: "Vision Thinking 1M" });
  +
  +		expect(modelHasCapability(plain, "thinking")).toBe(false);
  +		expect(modelHasCapability(plain, "vision")).toBe(false);
  +		expect(modelHasCapability(plain, "long-context")).toBe(false);
  +		expect(modelHasCapability(plain, "large-output")).toBe(false);
  +	});
  +
  +	test("shows badges for the same capabilities used by filters", () => {
  +		expect(modelCapabilityBadges(model({ contextWindow: 100_000, maxTokens: 16_000 }))).toEqual([
  +			"Long context",
  +			"Large output",
  +		]);
  +	});
  +});


